import{_ as i,c as t,o as e,a3 as r}from"./chunks/framework.CoV49S2T.js";const u=JSON.parse('{"title":"はじめに","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/introduction.md","filePath":"ja/guide/introduction.md","lastUpdated":1786595765000}'),o={name:"ja/guide/introduction.md"};function l(n,a,s,h,d,c){return e(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="はじめに" tabindex="-1">はじめに <a class="header-anchor" href="#はじめに" aria-label="Permalink to &quot;はじめに&quot;">​</a></h1><h2 id="clipboardxai-について" tabindex="-1">ClipboardxAI について <a class="header-anchor" href="#clipboardxai-について" aria-label="Permalink to &quot;ClipboardxAI について&quot;">​</a></h2><p><strong>ClipboardxAI</strong> は macOS 向けのスマートなクリップボードマネージャーです。テキスト・コード・リンクをコピーするたびに、それらが検索可能な履歴としてメニューバーに保存されます。ワンクリック、あるいは完全に自動で、そのクリップに対してアクションを実行できます。要約したり、翻訳したり、整えたり、クラウドの AI モデルに渡したりすることが可能です。</p><p>このアプリは、次の 2 種類のツールを中心に構成されています。</p><ul><li><strong>内蔵のローカルツール</strong> — Mac 上のみで動作し、ネットワーク接続を一切行いません。</li><li><strong>AI アクション</strong> — ご自身で設定したクラウドモデル（システムの Keychain に保存されたご自身の API key）を呼び出します。</li></ul><h2 id="主な機能" tabindex="-1">主な機能 <a class="header-anchor" href="#主な機能" aria-label="Permalink to &quot;主な機能&quot;">​</a></h2><h3 id="📋-クリップボード履歴" tabindex="-1">📋 クリップボード履歴 <a class="header-anchor" href="#📋-クリップボード履歴" aria-label="Permalink to &quot;📋 クリップボード履歴&quot;">​</a></h3><p>コピーしたものはすべて自動的にキャプチャされ、検索可能な履歴に保存されます。メニューバーから過去のクリップにいつでも戻ることができ、失われたスニペットともお別れです。</p><h3 id="⚡-スマートな提案" tabindex="-1">⚡ スマートな提案 <a class="header-anchor" href="#⚡-スマートな提案" aria-label="Permalink to &quot;⚡ スマートな提案&quot;">​</a></h3><p>ClipboardxAI は、現在のクリップに最も関連性の高いアクションを提案します。提案を受け入れることも、ツールの一覧から探すこともできます。</p><h3 id="🛠️-内蔵のローカルツール" tabindex="-1">🛠️ 内蔵のローカルツール <a class="header-anchor" href="#🛠️-内蔵のローカルツール" aria-label="Permalink to &quot;🛠️ 内蔵のローカルツール&quot;">​</a></h3><p>オフライン・プライベート・即時実行：</p><ul><li><strong>Extract Links（リンク抽出）</strong> — テキストブロックからすべての URL を取り出します。</li><li><strong>Count Stats（集計）</strong> — 単語数・文字数・行数・文の数をカウントします。</li><li><strong>Collapse Blank Lines（空白行の削除）</strong> — 貼り付けたテキストを一手順で整えます。</li></ul><p>今後もローカルツールは追加されていく予定ですが、いずれも端末の外には出ません。</p><h3 id="✨-ai-アクション" tabindex="-1">✨ AI アクション <a class="header-anchor" href="#✨-ai-アクション" aria-label="Permalink to &quot;✨ AI アクション&quot;">​</a></h3><p>現在のクリップをクラウドモデルに送信して、次のことができます。</p><ul><li><strong>Summarize（要約）</strong> — 長文の記事やスレッドを要約します。</li><li><strong>Translate（翻訳）</strong> — 言語間で翻訳します。</li><li><strong>Rewrite / polish（書き直し・推敲）</strong> — トーンと明快さを整えます。</li><li><strong>Marketplace</strong> の任意のアクションを実行します。</li></ul><h3 id="🛒-アクションマーケットプレイス" tabindex="-1">🛒 アクションマーケットプレイス <a class="header-anchor" href="#🛒-アクションマーケットプレイス" aria-label="Permalink to &quot;🛒 アクションマーケットプレイス&quot;">​</a></h3><p>コミュニティ製の AI アクションを閲覧し、ディープリンク（<code>clipboardxai://install?action=&lt;id&gt;</code>）からワンクリックでインストールできます。カテゴリーには Writing、Developer、Productivity、Translate、Social、Analytics があります。</p><h3 id="🔒-設計段階からプライベート" tabindex="-1">🔒 設計段階からプライベート <a class="header-anchor" href="#🔒-設計段階からプライベート" aria-label="Permalink to &quot;🔒 設計段階からプライベート&quot;">​</a></h3><p>クリップボードの履歴はお使いのデバイスに留まります。クラウド AI は**オプトイン（任意）**です。有効化した場合でも、コンテンツが送信されるのは <em>あなた</em> が選んだプロバイダーだけであり、Keychain に保存された API key が使用されます。私たちがクリップを受信したり保存したりすることは一切なく、アナリティクスやテレメトリも存在しません。</p><h2 id="システム要件" tabindex="-1">システム要件 <a class="header-anchor" href="#システム要件" aria-label="Permalink to &quot;システム要件&quot;">​</a></h2><ul><li><strong>オペレーティングシステム</strong>: macOS 14 Sonoma 以降</li><li><strong>CPU</strong>: Apple Silicon（M シリーズ）または Intel（64 ビット）</li><li><strong>メモリ</strong>: 最小 4 GB RAM、推奨 8 GB</li><li><strong>ストレージ</strong>: インストールに約 50 MB</li><li><strong>クラウド AI の場合</strong>: 対応プロバイダーの API key（DeepSeek、MiniMax、Zhipu GLM、Kimi、Mistral、Ollama、OpenAI、Anthropic、または Gemini）</li></ul><h2 id="対応言語" tabindex="-1">対応言語 <a class="header-anchor" href="#対応言語" aria-label="Permalink to &quot;対応言語&quot;">​</a></h2><p>このアプリと本サイトは、英語、简体中文（簡体字中国語）、繁體中文（繁体字中国語）、日本語、ドイツ語（German）、スペイン語（Spanish）、フランス語（French）の 7 言語に対応しています。</p><h2 id="はじめ方" tabindex="-1">はじめ方 <a class="header-anchor" href="#はじめ方" aria-label="Permalink to &quot;はじめ方&quot;">​</a></h2><p>ClipboardxAI を初めてお使いの場合は、まず<a href="/ja/guide/installation.html">インストールガイド</a>で Mac への導入を行い、次に<a href="/ja/guide/usage.html">使い方</a>をお読みいただくと、アクションの仕組みがわかります。</p>',27)])])}const g=i(o,[["render",l]]);export{u as __pageData,g as default};
